#[derive(Clone, Debug)]
pub struct OidcProviderClient {
    authorize: NativeRequestHandle<OidcProviderAuthorize>,
    exchange: NativeRequestHandle<OidcProviderExchange>,
    jwks: NativeRequestHandle<OidcProviderJwks>,
    metadata: NativeRequestHandle<OidcProviderMetadata>,
}
impl OidcProviderClient {
    pub fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_dependencies(dependencies)
    }

    pub fn from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_requirement(dependencies, requirement_id)
    }

    pub async fn authorize(&self, request: AuthorizeRequest) -> Result<AuthorizeResponse, OidcProviderAuthorizeInvocationError> {
        self.authorize.invoke(AUTHORIZE_OPERATION, request).await
            .map_err(OidcProviderAuthorizeInvocationError::Runtime)?
            .map_err(OidcProviderAuthorizeInvocationError::Domain)
    }

    pub async fn authorize_with_context(&self, context: InvocationContext, request: AuthorizeRequest) -> Result<AuthorizeResponse, OidcProviderAuthorizeInvocationError> {
        self.authorize.invoke_with_context(AUTHORIZE_OPERATION, context, request).await
            .map_err(OidcProviderAuthorizeInvocationError::Runtime)?
            .map_err(OidcProviderAuthorizeInvocationError::Domain)
    }

    pub async fn exchange(&self, request: ExchangeRequest) -> Result<ExchangeResponse, OidcProviderExchangeInvocationError> {
        self.exchange.invoke(EXCHANGE_OPERATION, request).await
            .map_err(OidcProviderExchangeInvocationError::Runtime)?
            .map_err(OidcProviderExchangeInvocationError::Domain)
    }

    pub async fn exchange_with_context(&self, context: InvocationContext, request: ExchangeRequest) -> Result<ExchangeResponse, OidcProviderExchangeInvocationError> {
        self.exchange.invoke_with_context(EXCHANGE_OPERATION, context, request).await
            .map_err(OidcProviderExchangeInvocationError::Runtime)?
            .map_err(OidcProviderExchangeInvocationError::Domain)
    }

    pub async fn jwks(&self, request: EmptyRequest) -> Result<JwksResponse, OidcProviderJwksInvocationError> {
        self.jwks.invoke(JWKS_OPERATION, request).await
            .map_err(OidcProviderJwksInvocationError::Runtime)?
            .map_err(OidcProviderJwksInvocationError::Domain)
    }

    pub async fn jwks_with_context(&self, context: InvocationContext, request: EmptyRequest) -> Result<JwksResponse, OidcProviderJwksInvocationError> {
        self.jwks.invoke_with_context(JWKS_OPERATION, context, request).await
            .map_err(OidcProviderJwksInvocationError::Runtime)?
            .map_err(OidcProviderJwksInvocationError::Domain)
    }

    pub async fn metadata(&self, request: EmptyRequest) -> Result<MetadataResponse, OidcProviderMetadataInvocationError> {
        self.metadata.invoke(METADATA_OPERATION, request).await
            .map_err(OidcProviderMetadataInvocationError::Runtime)?
            .map_err(OidcProviderMetadataInvocationError::Domain)
    }

    pub async fn metadata_with_context(&self, context: InvocationContext, request: EmptyRequest) -> Result<MetadataResponse, OidcProviderMetadataInvocationError> {
        self.metadata.invoke_with_context(METADATA_OPERATION, context, request).await
            .map_err(OidcProviderMetadataInvocationError::Runtime)?
            .map_err(OidcProviderMetadataInvocationError::Domain)
    }
}

impl CapabilityClient for OidcProviderClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            authorize: dependencies.one::<OidcProviderAuthorize>()?,
            exchange: dependencies.one::<OidcProviderExchange>()?,
            jwks: dependencies.one::<OidcProviderJwks>()?,
            metadata: dependencies.one::<OidcProviderMetadata>()?,
        })
    }

    fn from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Self, RuntimeFailure> {
        let dependencies = dependencies.requirement(requirement_id)?;
        Self::from_dependencies(&dependencies)
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for OidcProviderClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    authorize: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<OidcProviderAuthorize>()?,
                    exchange: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<OidcProviderExchange>()?,
                    jwks: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<OidcProviderJwks>()?,
                    metadata: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<OidcProviderMetadata>()?,
                    },
                ))
            })
            .collect()
    }

    fn many_from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        let dependencies = dependencies.requirement(requirement_id)?;
        Self::many_from_dependencies(&dependencies)
    }
}

